import { isMac, isRemoteShell } from '../lib/platform.js';
const action = isMac ? 'Cmd' : 'Ctrl';
const paste = isMac ? 'Cmd' : 'Alt';
const copyHotkeys = isMac ? [['Cmd+C', 'copiar seleção'], ['Ctrl+C', 'limpar rascunho / sair']] : isRemoteShell() ? [['Cmd+C', 'copiar seleção quando encaminhado pelo terminal'], ['Ctrl+C', 'copiar seleção / limpar rascunho / sair']] : [['Ctrl+C', 'copiar seleção / limpar rascunho / sair']];
